-- Original installed bIA actions, separate from bIx furniture knowledge.
CREATE TABLE native_ranch_building_learning_actions (
    item_ref integer PRIMARY KEY CHECK (item_ref > 0),
    action_id integer NOT NULL CHECK (action_id > 0),
    profession_id integer NOT NULL CHECK (profession_id > 0),
    minimum_level integer NOT NULL CHECK (minimum_level >= 0),
    building_refs integer[] NOT NULL CHECK (cardinality(building_refs) > 0),
    native_class text NOT NULL CHECK (native_class = 'bIA'),
    source_sha256 text NOT NULL
);
CREATE TABLE account_ranch_building_knowledge (
    account_id bigint NOT NULL REFERENCES accounts(id),
    building_ref integer NOT NULL CHECK (building_ref > 0),
    learned_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (account_id, building_ref)
);
CREATE TABLE ranch_building_learning_receipts (
    account_id bigint NOT NULL REFERENCES accounts(id),
    source_uid bigint NOT NULL CHECK (source_uid > 0),
    character_id bigint NOT NULL REFERENCES characters(id),
    source_ref integer NOT NULL CHECK (source_ref > 0),
    action_id integer NOT NULL CHECK (action_id > 0),
    learned_refs integer[] NOT NULL CHECK (cardinality(learned_refs) > 0),
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (account_id, source_uid)
);
